package main
import(
"bytes"
"crypto/cipher"
"crypto/ecdh"
"crypto/mlkem"
"crypto/rand"
"fmt"
"io"
"log"
"net"
"strconv"
"strings"
"sync"
"sync/atomic"
"time"
"lukechampine.com/blake3"
)
type ServerSession struct{PfsKey[]byte;Expire time.Time;NfsKeys sync.Map;NfsKeysCnt int32}
type ServerInstance struct{NfsSKeys[]any;NfsPKeysBytes[][]byte;Hash32s[][32]byte;RelaysLength int;Sessions map[[16]byte]*ServerSession;Tickets[][16]byte;Lasts map[int64][16]byte;Closed bool;RWLock sync.RWMutex;handshakeLim sync.Map}
func(i*ServerInstance)Init(nfsSKeysBytes[][]byte)error{if i.NfsSKeys!=nil{return fmt.Errorf("already initialized")};l:=len(nfsSKeysBytes);if l==0{return fmt.Errorf("empty nfsSKeysBytes")};i.NfsSKeys=make([]any,l);i.NfsPKeysBytes=make([][]byte,l);i.Hash32s=make([][32]byte,l);for j,k:=range nfsSKeysBytes{if len(k)==x25519KeySize{priv,err:=ecdh.X25519().NewPrivateKey(k);if err!=nil{return err};i.NfsSKeys[j]=priv;i.NfsPKeysBytes[j]=priv.PublicKey().Bytes();i.RelaysLength+=x25519KeySize+x25519KeySize}else{dk,err:=mlkem.NewDecapsulationKey768(k);if err!=nil{return err};i.NfsSKeys[j]=dk;i.NfsPKeysBytes[j]=dk.EncapsulationKey().Bytes();i.RelaysLength+=mlkemCTSize+x25519KeySize};i.Hash32s[j]=blake3.Sum256(i.NfsPKeysBytes[j])};i.RelaysLength-=x25519KeySize;i.Sessions=make(map[[16]byte]*ServerSession);i.Tickets=make([][16]byte,0,1024);i.Lasts=make(map[int64][16]byte);go i.cleanup();return nil}
func(i*ServerInstance)cleanup(){ticker:=time.NewTicker(cleanupInterval);defer ticker.Stop();for{<-ticker.C;i.RWLock.Lock();if i.Closed{i.RWLock.Unlock();return};now:=time.Now();minute:=now.Unix()/60;last:=i.Lasts[minute];delete(i.Lasts,minute);delete(i.Lasts,minute-1);if last!=[16]byte{}{found:=-1;for j,ticket:=range i.Tickets{if ticket==last{found=j;break}};if found!=-1{delete(i.Sessions,last);i.Tickets=append(i.Tickets[:found],i.Tickets[found+1:]...)}};i.RWLock.Unlock();i.handshakeLim.Range(func(key,value interface{})bool{if now.Sub(value.(time.Time))>rateCleanupAge{i.handshakeLim.Delete(key)};return true})}}
func(i*ServerInstance)Close()error{i.RWLock.Lock();i.Closed=true;i.RWLock.Unlock();return nil}
func(i*ServerInstance)checkRate(addr string)bool{now:=time.Now();last,_:=i.handshakeLim.LoadOrStore(addr,now);if last.(time.Time).Add(handshakeRate).After(now){return false};i.handshakeLim.Store(addr,now);return true}
func(i*ServerInstance)Handshake(conn net.Conn)(*CommonConn,error){remoteAddr:=conn.RemoteAddr().String();if!i.checkRate(remoteAddr){return nil,fmt.Errorf("handshake rate limit exceeded")};if i.NfsSKeys==nil{return nil,fmt.Errorf("uninitialized")};c:=NewCommonConn(conn);ivAndRelays:=make([]byte,16+i.RelaysLength);if _,err:=io.ReadFull(conn,ivAndRelays);err!=nil{return nil,fmt.Errorf("read iv and relays: %w",err)};iv:=ivAndRelays[:16];relays:=ivAndRelays[16:];var nfsKey[]byte;var lastCTR cipher.Stream;for j,k:=range i.NfsSKeys{if lastCTR!=nil{lastCTR.XORKeyStream(relays,relays[:x25519KeySize])};index:=x25519KeySize;if _,ok:=k.(*mlkem.DecapsulationKey768);ok{index=mlkemCTSize};if priv,ok:=k.(*ecdh.PrivateKey);ok{pub,err:=ecdh.X25519().NewPublicKey(relays[:index]);if err!=nil{return nil,fmt.Errorf("parse x25519 public key: %w",err)};if pub.Bytes()[31]>127{return nil,fmt.Errorf("x25519 high bit not zero")};nfsKey,err=priv.ECDH(pub);if err!=nil{return nil,fmt.Errorf("x25519 ECDH: %w",err)}}else if dk,ok:=k.(*mlkem.DecapsulationKey768);ok{var err error;nfsKey,err=dk.Decapsulate(relays[:index]);if err!=nil{return nil,fmt.Errorf("mlkem decapsulate: %w",err)}};if j==len(i.NfsSKeys)-1{break};relays=relays[index:];lastCTR=NewCTR(nfsKey,iv);lastCTR.XORKeyStream(relays,relays[:x25519KeySize]);if!bytes.Equal(relays[:x25519KeySize],i.Hash32s[j+1][:]){return nil,fmt.Errorf("hash mismatch")};relays=relays[x25519KeySize:]};nfsAEAD:=NewAEAD(iv,nfsKey);encryptedLength:=make([]byte,18);if _,err:=io.ReadFull(conn,encryptedLength);err!=nil{return nil,fmt.Errorf("read encrypted length: %w",err)};decryptedLength:=make([]byte,2);if _,err:=nfsAEAD.Open(decryptedLength[:0],nil,encryptedLength,nil);err!=nil{return nil,fmt.Errorf("decrypt length: %w",err)};length:=DecodeLength(decryptedLength);if length==x25519KeySize{encryptedTicket:=make([]byte,x25519KeySize);if _,err:=io.ReadFull(conn,encryptedTicket);err!=nil{return nil,fmt.Errorf("read encrypted ticket: %w",err)};ticket,err:=nfsAEAD.Open(nil,nil,encryptedTicket,nil);if err!=nil{return nil,fmt.Errorf("decrypt ticket: %w",err)};var ticketKey[16]byte;copy(ticketKey[:],ticket);i.RWLock.RLock();s:=i.Sessions[ticketKey];i.RWLock.RUnlock();if s==nil{noises:=make([]byte,512);if _,err:=rand.Read(noises);err!=nil{return nil,fmt.Errorf("rand read noises: %w",err)};conn.Write(noises);return nil,fmt.Errorf("expired ticket")};if time.Now().After(s.Expire){return nil,fmt.Errorf("ticket expired")};cnt:=atomic.AddInt32(&s.NfsKeysCnt,1);if cnt>maxNfsKeys{atomic.AddInt32(&s.NfsKeysCnt,-1);return nil,fmt.Errorf("too many replay attempts")};if _,loaded:=s.NfsKeys.LoadOrStore([32]byte(nfsKey),true);loaded{atomic.AddInt32(&s.NfsKeysCnt,-1);return nil,fmt.Errorf("replay detected")};unitedKey:=append(s.PfsKey,nfsKey...);c.UnitedKey=unitedKey;serverRandom:=make([]byte,16);if _,err:=rand.Read(serverRandom);err!=nil{return nil,fmt.Errorf("rand read server random: %w",err)};if _,err:=conn.Write(serverRandom);err!=nil{return nil,fmt.Errorf("write server random: %w",err)};c.AEAD=NewAEAD(serverRandom,unitedKey);c.PeerAEAD=NewAEAD(encryptedTicket,unitedKey);return c,nil};if length<mlkemPubSize+x25519KeySize+aeadOverhead{return nil,fmt.Errorf("too short length")};encryptedPfsPublicKey:=make([]byte,length);if _,err:=io.ReadFull(conn,encryptedPfsPublicKey);err!=nil{return nil,fmt.Errorf("read encrypted pfs key: %w",err)};if _,err:=nfsAEAD.Open(encryptedPfsPublicKey[:0],MaxNonce,encryptedPfsPublicKey,nil);err!=nil{return nil,fmt.Errorf("decrypt pfs key: %w",err)};mlkem768EKey,err:=mlkem.NewEncapsulationKey768(encryptedPfsPublicKey[:mlkemPubSize]);if err!=nil{return nil,fmt.Errorf("parse mlkem public key: %w",err)};mlkem768Key,encapsulatedPfsKey:=mlkem768EKey.Encapsulate();peerX25519PKey,err:=ecdh.X25519().NewPublicKey(encryptedPfsPublicKey[mlkemPubSize:mlkemPubSize+x25519KeySize]);if err!=nil{return nil,fmt.Errorf("parse peer x25519 key: %w",err)};x25519SKey,err:=ecdh.X25519().GenerateKey(rand.Reader);if err!=nil{return nil,fmt.Errorf("generate x25519 key: %w",err)};x25519Key,err:=x25519SKey.ECDH(peerX25519PKey);if err!=nil{return nil,fmt.Errorf("x25519 ECDH: %w",err)};pfsKey:=make([]byte,x25519KeySize+x25519KeySize);copy(pfsKey,mlkem768Key);copy(pfsKey[x25519KeySize:],x25519Key);serverPfsPublicKey:=append(encapsulatedPfsKey,x25519SKey.PublicKey().Bytes()...);unitedKey:=append(pfsKey,nfsKey...);c.UnitedKey=unitedKey;c.AEAD=NewAEAD(serverPfsPublicKey,unitedKey);clientPfsPublicKey:=encryptedPfsPublicKey[:mlkemPubSize+x25519KeySize];c.PeerAEAD=NewAEAD(clientPfsPublicKey,unitedKey);ticket:=[16]byte{};if _,err:=rand.Read(ticket[:]);err!=nil{return nil,fmt.Errorf("rand read ticket: %w",err)};seconds,err:=randBetween(50,60);if err!=nil{log.Printf("randBetween failed: %v, using default 60s",err);seconds=60};copy(ticket[:],EncodeLength(int(seconds)));expireTime:=time.Now().Add(time.Duration(seconds)*time.Second);i.RWLock.Lock();i.Lasts[(time.Now().Unix()+60)/60+2]=ticket;i.Tickets=append(i.Tickets,ticket);i.Sessions[ticket]=&ServerSession{PfsKey:pfsKey,Expire:expireTime,NfsKeys:sync.Map{},NfsKeysCnt:0};i.RWLock.Unlock();serverHello:=make([]byte,mlkemCTSize+x25519KeySize+aeadOverhead+x25519KeySize);nfsAEAD.Seal(serverHello[:0],MaxNonce,serverPfsPublicKey,nil);c.AEAD.Seal(serverHello[mlkemCTSize+x25519KeySize+aeadOverhead:],nil,ticket[:],nil);if _,err:=conn.Write(serverHello);err!=nil{return nil,fmt.Errorf("write server hello: %w",err)};return c,nil}
func NewServerConn(conn net.Conn,cfg*Config)(*FakeHTTPConn,error){fc:=&FakeHTTPConn{RawConn:NewRawConn(conn),host:cfg.Host,isClient:false,chunkBuf:make([]byte,0,64*1024)};if err:=fc.serverHandshake();err!=nil{return nil,err};return fc,nil}
func(c*FakeHTTPConn)serverHandshake()error{header,err:=c.ReadUntilBlank();if err!=nil{return fmt.Errorf("read headers: %w",err)};lines:=strings.Split(header,"\r\n");if len(lines)==0||!strings.HasPrefix(lines[0],"GET "){return fmt.Errorf("not a GET request")};resp:="HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nTransfer-Encoding: chunked\r\nConnection: keep-alive\r\n\r\n";if _,err:=c.WriteString(resp);err!=nil{return fmt.Errorf("write response: %w",err)};c.handshake=true;return nil}
func main(){cfg,err:=LoadConfig("server.json");if err!=nil{log.Fatalf("load config: %v",err)};server:=&ServerInstance{};if err:=server.Init(cfg.Keys);err!=nil{log.Fatalf("init server: %v",err)};ln,err:=net.Listen("tcp",cfg.IP+":"+strconv.Itoa(cfg.Port));if err!=nil{log.Fatalf("listen: %v",err)};defer ln.Close();log.Printf("Server listening on %s:%d",cfg.IP,cfg.Port);for{raw,err:=ln.Accept();if err!=nil{log.Printf("accept error: %v",err);continue};go func(raw net.Conn){defer raw.Close();httpConn,err:=NewServerConn(raw,cfg);if err!=nil{log.Printf("server handshake error: %v",err);return};defer httpConn.Close();sudokuConn,err:=NewPackedTCPConn(httpConn,cfg.UUID);if err!=nil{log.Printf("packed tcp error: %v",err);return};encConn,err:=server.Handshake(sudokuConn);if err!=nil{log.Printf("handshake error: %v",err);return};buf:=make([]byte,4096);n,err:=encConn.Read(buf);if err==nil{encConn.Write(buf[:n])}}(raw)}}